import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture from assets
  const textureAsset = ctx.textureLoader.load(config.assets.imageUrl);

  // Create plane geometry with aspect ratio 512 / 320 = 1.6
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Create material with texture node
  const material = new MeshBasicNodeMaterial();
  material.colorNode = texture(textureAsset);
  material.transparent = true;
  material.side = THREE.DoubleSide;

  // Create mesh and add to group
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply position from config
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x ?? 0,
      config.scenePosition.y ?? 0,
      config.scenePosition.z ?? 0
    );
  }

  // Billboard rotation: face camera (rotate π around Y axis)
  group.rotation.y = Math.PI;

  // Apply scale from config
  if (config.scale) {
    group.scale.set(
      config.scale.x ?? 1,
      config.scale.y ?? 1,
      config.scale.z ?? 1
    );
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureAsset.dispose();
  };

  return group;
}
